'use strict'

// Public entry point. `binding.js` is the loader generated by napi-rs; this file adds
// the JavaScript half of `renderEmlStream`, which streams attachment bodies into a
// template rendered by the native MIME builder.

const { Buffer } = require('node:buffer')
const binding = require('./binding.js')

const ReadableStream =
  globalThis.ReadableStream || require('node:stream/web').ReadableStream

const LINE_BYTES = 57 // 57 input bytes encode to one 76-character base64 line.
const LINE_LENGTH = 76

/** Base64-encodes `bytes` as 76-character lines joined by CRLF. */
function encodeLines(bytes, leadingBreak) {
  const encoded = bytes.toString('base64')
  const lines = Math.ceil(encoded.length / LINE_LENGTH)
  // Not from the shared pool: consumers may read or transfer `chunk.buffer`.
  const out = Buffer.allocUnsafeSlow(encoded.length + (lines - 1 + (leadingBreak ? 1 : 0)) * 2)
  let offset = 0
  for (let i = 0; i < encoded.length; i += LINE_LENGTH) {
    if (i > 0 || leadingBreak) {
      out[offset++] = 13
      out[offset++] = 10
    }
    offset += out.write(encoded.slice(i, i + LINE_LENGTH), offset, 'latin1')
  }
  return out
}

function toBuffer(chunk) {
  if (!(chunk instanceof Uint8Array)) {
    throw new TypeError('attachment streams must yield Uint8Array chunks')
  }
  return Buffer.from(chunk.buffer, chunk.byteOffset, chunk.byteLength)
}

/** Wraps whatever `open()` resolved to as `{ read, cancel }`. */
function toReader(source) {
  if (source instanceof Uint8Array) {
    let done = false
    return {
      read: async () => (done ? { done: true } : ((done = true), { done: false, value: source })),
      cancel: async () => {
        done = true
      },
    }
  }
  if (source && typeof source.getReader === 'function') {
    const reader = source.getReader()
    let finished = false
    return {
      read: async () => {
        const result = await reader.read()
        if (result.done) {
          finished = true
          reader.releaseLock()
        }
        return result
      },
      cancel: async (reason) => {
        if (!finished) {
          finished = true
          await reader.cancel(reason)
        }
      },
    }
  }
  if (source && typeof source[Symbol.asyncIterator] === 'function') {
    const iterator = source[Symbol.asyncIterator]()
    let finished = false
    return {
      read: async () => {
        const result = await iterator.next()
        if (result.done) finished = true
        return result
      },
      cancel: async () => {
        if (!finished) {
          finished = true
          // Destroy a Node.js Readable directly: returning an iterator that was never
          // read skips its cleanup, and an async generator queues return() behind a
          // pending next(), so a stalled source would never close. No error argument:
          // that would emit 'error' with no listener attached.
          if (typeof source.destroy === 'function') source.destroy()
          if (typeof iterator.return === 'function') {
            Promise.resolve()
              .then(() => iterator.return())
              .catch(() => {})
          }
        }
      },
    }
  }
  throw new TypeError(
    'attachment open() must resolve to a ReadableStream, an async iterable of Uint8Array, a Uint8Array, or null',
  )
}

/** Yields an attachment's base64 body, carrying partial lines across source chunks. */
async function* base64Body(reader) {
  let carry = Buffer.alloc(0)
  let leadingBreak = false
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    const chunk = toBuffer(value)
    if (chunk.length === 0) continue
    const data = carry.length ? Buffer.concat([carry, chunk]) : chunk
    const usable = data.length - (data.length % LINE_BYTES)
    // Copy the remainder so a large source chunk is not retained through a view.
    carry = Buffer.from(data.subarray(usable))
    if (usable === 0) continue
    yield encodeLines(data.subarray(0, usable), leadingBreak)
    leadingBreak = true
  }
  if (carry.length) yield encodeLines(carry, leadingBreak)
}

/**
 * Renders a draft like `renderEml`, streaming each lazy attachment's body from the
 * source its `open()` returns. See index.d.ts for the full contract.
 */
async function renderEmlStream(options) {
  const input = options || {}
  const lazy = []
  const attachments = (input.attachments || []).map((attachment, index) => {
    if (typeof attachment.open !== 'function') return attachment
    if (attachment.content !== undefined) {
      throw new TypeError(`attachment ${index} has both content and open`)
    }
    lazy.push(index)
    const { open, ...rest } = attachment
    return { ...rest, content: Buffer.alloc(0) }
  })
  const { bytes: template, parts } = binding.renderEmlTemplate(
    { ...input, attachments: input.attachments ? attachments : undefined },
    lazy,
  )

  // openings[i] is the pending open of parts[i]; it resolves to a reader or null.
  const openings = []
  const readers = []
  let cancelled = false
  const open = (i) => {
    if (i >= parts.length || (cancelled && !openings[i])) return undefined
    if (!openings[i]) {
      const opener = input.attachments[parts[i].attachment].open
      openings[i] = Promise.resolve()
        .then(() => opener())
        .then((source) => {
          const reader = source == null ? null : toReader(source)
          readers[i] = reader
          if (reader && cancelled) reader.cancel().catch(() => {})
          return reader
        })
      openings[i].catch(() => {})
    }
    return openings[i]
  }
  // Cancels every source opened so far. Sources still opening are cancelled when
  // they arrive instead of being awaited, so a slow open() cannot delay this.
  const cancelOpened = (reason) => {
    cancelled = true
    return Promise.allSettled(readers.map((reader) => reader && reader.cancel(reason)))
  }

  async function* chunks() {
    let offset = 0
    for (let i = 0; i < parts.length; i++) {
      const part = parts[i]
      const reader = await open(i)
      if (cancelled) return
      open(i + 1)
      if (!reader) {
        if (part.start > offset) yield template.subarray(offset, part.start)
        offset = part.end
        continue
      }
      yield template.subarray(offset, part.bodyStart)
      yield* base64Body(reader)
      if (cancelled) return
      offset = part.bodyStart
    }
    yield template.subarray(offset)
  }

  try {
    await open(0)
  } catch (error) {
    await cancelOpened(error)
    throw error
  }

  const iterator = chunks()
  return new ReadableStream(
    {
      async pull(controller) {
        try {
          while (true) {
            const { done, value } = await iterator.next()
            if (done) {
              controller.close()
              return
            }
            if (value.length) {
              controller.enqueue(value)
              return
            }
          }
        } catch (error) {
          controller.error(error)
          cancelOpened(error)
        }
      },
      async cancel(reason) {
        // Cancel the sources first: a pull may be waiting on one of them, and the
        // generator cannot finish until that read settles.
        await cancelOpened(reason)
        iterator.return().catch(() => {})
      },
    },
    { highWaterMark: 0 },
  )
}

module.exports = Object.assign({}, binding)
module.exports.Transporter = binding.Transporter
module.exports.createTransport = binding.createTransport
module.exports.renderEml = binding.renderEml
module.exports.renderEmlBase64 = binding.renderEmlBase64
module.exports.renderEmlStream = renderEmlStream
module.exports.renderEmlTemplate = binding.renderEmlTemplate
